package com.aistock.common.marketrefs;
import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static com.aistock.common.marketrefs.MarketReferenceRecords.*;
class MarketReferenceContractTest {
 static final String V="11111111-1111-1111-1111-111111111111";static final Instant NOW=Instant.parse("2026-10-28T00:00:00Z");
 OwnerResult owner(String owner){return new OwnerResult(owner,V,NOW,"COMPLETE",null,List.of(new Group("snapshot","快照记录","COMPLETE","0",null)));}
 @Test void acceptsCompleteZeroButNotUnknownZeroOrDuplicateGroups(){var v=owner("prediction");assertDoesNotThrow(()->MarketReferenceInput.validateOwner(v,"prediction",V));assertThrows(IllegalArgumentException.class,()->MarketReferenceInput.validateOwner(new OwnerResult("prediction",V,NOW,"PARTIAL","REFERENCE_PARTIAL",List.of(new Group("snapshot","快照记录","UNKNOWN","0","REFERENCE_QUERY_UNAVAILABLE"))),"prediction",V));assertThrows(IllegalArgumentException.class,()->MarketReferenceInput.validateOwner(new OwnerResult("prediction",V,NOW,"COMPLETE",null,List.of(v.groups().get(0),v.groups().get(0))),"prediction",V));}
 @Test void rejectsMismatchAndNumericJsonCount(){assertThrows(IllegalArgumentException.class,()->MarketReferenceInput.validateOwner(owner("scheduler"),"prediction",V));assertThrows(IllegalArgumentException.class,()->MarketReferenceInput.decodeOwner(("{\"owner\":\"prediction\",\"versionId\":\""+V+"\",\"queriedAt\":\"2026-10-28T00:00:00Z\",\"state\":\"COMPLETE\",\"reasonCode\":null,\"groups\":[{\"category\":\"snapshot\",\"label\":\"快照\",\"state\":\"COMPLETE\",\"rows\":0,\"reasonCode\":null}]}").getBytes(java.nio.charset.StandardCharsets.UTF_8),"prediction",V));}
 @Test void validatesSqlIdentifiersAndImmutableDefinition(){assertThrows(IllegalArgumentException.class,()->new Source("x","记录","stock_other.secret",List.of("version_id"),List.of()));assertThrows(IllegalArgumentException.class,()->new Source("x","记录","safe",List.of("version_id or 1=1"),List.of()));var columns=new ArrayList<>(List.of("version_id"));var source=new Source("x","记录","safe",columns,List.of());columns.clear();assertEquals(1,source.directColumns().size());}
 @Test void completeReportRequiresEveryExpectedOwnerAndNoUnsafeFields(){var v=new Report("SH600030",V,"baostock","RAW","AVAILABLE",true,NOW,NOW,"COMPLETE",List.of(owner("prediction"),owner("scheduler"),owner("notification")));assertDoesNotThrow(()->MarketReferenceInput.validateReport(v,"SH600030",V));assertThrows(IllegalArgumentException.class,()->MarketReferenceInput.validateReport(new Report("SH600030",V,"baostock","RAW","AVAILABLE",true,NOW,NOW,"COMPLETE",List.of(owner("prediction"))),"SH600030",V));assertFalse(MarketReferenceInput.publicPath("/api/v1/admin/market-data/SH600030/versions/"+V+"/references/extra"));}
}
